                    sm_add_cand(scr, pls_seal(), r, crate::port::cells_at(tmp, 0) - crate::port::cells_at(tmp, 2), crate::port::cells_at(tmp, 1) - crate::port::cells_at(tmp, 2), crate::port::cells_at(tmp, 0) + crate::port::cells_at(tmp, 2), crate::port::cells_at(tmp, 1) + crate::port::cells_at(tmp, 2), crate::port::cells_at(tmp, 0), crate::port::cells_at(tmp, 1), crate::port::cells_at(tmp, 2), ink, fl);
